const JUNO_CURL_IN_PLAIN = [
"                                        ",
"                 .......                ",
"           ..::::::::::::::..           ",
"         .:::::::::::::::::::::         ",
"       ::::::::::::::      .:::::       ",
"     .:::::::::...          .:::::.     ",
"    .::::::::                .:::::.    ",
"    :::::::.               .::::::::    ",
"   .:::::::        .::.     .:::::::.   ",
"   ::::::::    ..:::::.:.   .::::::::   ",
"   :::::::.   :: .:::. ::  .:::::::::   ",
"   .:::::::   ::::::.:::. :::::::::::   ",
"    :::::::. ..:.:::::...:::::::::::    ",
"    .::::::. ::::.     ::::::::::::.    ",
"     .::::::::..         .::::::::.     ",
"       .:::::              .::::.       ",
"         .::.         :     ::.         ",
"                     .                  ",
"                                        ",
"                                        ",
];

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Every frame is the same width and height line-for-line, so redrawing
// is just "move the cursor back up and print again" — no explicit
// clear codes needed, the new line always fully overwrites the old one.
function moveCursorUp(n) {
  process.stdout.write(`\x1b[${n}A`);
}

function paint(lines) {
  process.stdout.write(lines.join('\n') + '\n');
}

// Skips the animation (prints the neutral frame once, plain characters
// only) for non-TTY output — piped/redirected runs, CI logs — where
// cursor movement and color escape codes would print as garbage
// instead of animating.
export async function playJunoIntro(pc) {
  const color = pc.isColorSupported;
  const frame = (ansi, plain) => (color ? ansi : plain);
  const rows = JUNO_NEUTRAL_ANSI.length;

  if (!process.stdout.isTTY) {
    paint(JUNO_NEUTRAL_PLAIN);
    return;
  }

  const redraw = async (ansi, plain, holdMs) => {
    moveCursorUp(rows);
    paint(frame(ansi, plain));
    await sleep(holdMs);
  };

  paint(frame(JUNO_NEUTRAL_ANSI, JUNO_NEUTRAL_PLAIN));
  await sleep(450);
  await redraw(JUNO_CURL_OUT_ANSI, JUNO_CURL_OUT_PLAIN, 220);
  await redraw(JUNO_NEUTRAL_ANSI, JUNO_NEUTRAL_PLAIN, 200);
  await redraw(JUNO_CURL_IN_ANSI, JUNO_CURL_IN_PLAIN, 220);
  await redraw(JUNO_NEUTRAL_ANSI, JUNO_NEUTRAL_PLAIN, 350);
  await redraw(JUNO_WINK_ANSI, JUNO_WINK_PLAIN, 260);
  await redraw(JUNO_NEUTRAL_ANSI, JUNO_NEUTRAL_PLAIN, 0);
}
